import{_ as e,o as l,c as t,a2 as i}from"./chunks/framework.F7eQ-ohH.js";const r="/bzygq/assets/quesion_imgs_4a01762911584a408ea3b2e3394e43c1.B6Kv3cE8.png",o="/bzygq/assets/quesion_imgs_fe8a8a778af6452c93a08ce6d613f65e.f__I1ZVe.png",p="/bzygq/assets/quesion_imgs_d460242b56ed4d258aea7955d96325ae.xmp9mGcp.png",h="/bzygq/assets/quesion_imgs_d7a0687e7dac4a6f89832e5114af430e.CFSVTnaW.png",s="/bzygq/assets/quesion_imgs_5315e815000849f2adfa712ee5f4836b.C6b1QRl9.png",n="/bzygq/assets/quesion_imgs_88a5303152834d559ac4a1c5e97f7dfc.DJ_51lUQ.png",d="/bzygq/assets/quesion_imgs_1cf30672640b4f52b3a90f77583e7d02.wg-TsVJT.png",C="/bzygq/assets/quesion_imgs_57cf3798acf44891a5ba66d3e9f2916f.C1TbJGzG.png",P="/bzygq/assets/quesion_imgs_c83fca40cc3d4a248e2a59312e942f74.BnBLNn3D.png",f=JSON.parse('{"title":"中断系统","description":"","frontmatter":{},"headers":[],"relativePath":"科技岗专业课/计算机组成原理/4、中断系统.md","filePath":"科技岗专业课/计算机组成原理/4、中断系统.md","lastUpdated":1788883925000}'),c={name:"科技岗专业课/计算机组成原理/4、中断系统.md"};function b(U,a,u,q,_,m){return l(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="中断系统" tabindex="-1"><strong>中断系统</strong> <a class="header-anchor" href="#中断系统" aria-label="Permalink to &quot;**中断系统**&quot;">​</a></h1><h2 id="中断概念" tabindex="-1">中断概念 <a class="header-anchor" href="#中断概念" aria-label="Permalink to &quot;中断概念&quot;">​</a></h2><p>中断是计算机系统实现异步处理、提升效率与实时性的核心机制，其定义、触发因素及处理流程共同构成了中断机制的基础框架，是理解后续功能与分类的核心前提。</p><h2 id="中断的定义、触发因素与处理流程" tabindex="-1">中断的定义、触发因素与处理流程 <a class="header-anchor" href="#中断的定义、触发因素与处理流程" aria-label="Permalink to &quot;中断的定义、触发因素与处理流程&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>中断的本质是 CPU 对系统事件的异步响应机制：当外部设备请求、内部程序异常或特定指令触发时，CPU 暂停当前程序，优先处理该事件，完成后返回原程序继续执行，核心价值在于实现多任务并发、保障实时响应。</p><p>引起中断的因素（即中断源）可归纳为五大类：一是人为设置的中断（如陷阱指令）；二是程序性事故（溢出、非法操作码、非法除法等）；三是硬件故障（内存错误、设备异常等）；四是 I/O 设备请求（硬盘读写、外设交互等）；五是外部事件（键盘按键、时钟信号等），这些中断源覆盖了硬件与软件、主动与被动等多种场景。</p><p>中断处理遵循标准化流程，分为四个关键阶段：①中断请求：中断源通过硬件线路（如 IRQ）或内部逻辑向 CPU 发送信号；②中断响应：CPU 执行完当前指令后，检测到未屏蔽的中断，保存程序断点（PC 指针、寄存器状态）至栈中，并获取中断服务程序（ISR）入口地址；③中断处理：CPU 跳转至 ISR 执行具体逻辑（如读取外设数据、修复程序错误）；④中断返回：从栈中恢复断点与寄存器状态，回到原程序继续执行。</p><p>明确中断的定义、梳理触发源及标准化处理流程，是理解后续中断作用与分类的前提，为深入掌握中断机制的实际应用提供了基础认知。</p><h2 id="中断作用" tabindex="-1">中断作用 <a class="header-anchor" href="#中断作用" aria-label="Permalink to &quot;中断作用&quot;">​</a></h2><p>中断机制贯穿计算机系统运行的全流程，其核心价值体现在硬件协作、故障处理、人机交互等多个关键场景，是保障系统高效、稳定、灵活运行的核心支撑。</p><p>中断的具体作用可概括为七大核心方向：​</p><ol><li>硬件协作与效率提升：实现 CPU 与 I/O 设备并行工作，CPU 在 I/O 设备执行操作时可处理其他任务（如硬盘读写时进行计算），大幅提升系统整体吞吐量；</li><li>故障与错误处理：及时响应硬件故障（内存错误）与软件异常（除零错误），通过修复、记录或终止等方式保障系统稳定；</li><li>人机交互支持：让用户操作（键盘按键、鼠标点击）快速触发系统响应（如游戏中按键即时生效），提升交互流畅性；</li><li>多任务与分时基础：作为多道程序、分时操作的核心，通过中断实现程序切换（如时钟中断驱动任务调度），营造多程序 “同时运行” 的体验；</li><li>实时响应保障：为工业控制、航空航天等场景提供快速响应，确保传感器数据、关键指令等得到即时处理；</li><li>系统权限切换：通过软中断实现应用程序与操作系统的权限切换，支撑文件读写等系统服务请求；</li><li>多处理器协同：在多 CPU 系统中，实现处理器间信息交互与任务分工（如分布式计算），提升系统性能与扩展性。</li></ol><p>从硬件并行到软件协作，从故障处理到实时响应，中断的多元作用覆盖了计算机系统从底层硬件到上层应用的全链路需求，是连接硬件与软件、协调各类任务的关键桥梁，直接决定了系统的综合性能与可靠性。</p><h2 id="中断类型" tabindex="-1">中断类型 <a class="header-anchor" href="#中断类型" aria-label="Permalink to &quot;中断类型&quot;">​</a></h2><p>根据触发源、实现方式的不同，中断可分为内中断与外中断、硬中断与软中断两大核心分类，不同类型的中断在触发场景、处理逻辑上存在显著差异，适配不同的系统需求。</p><h3 id="内中断和外中断" tabindex="-1">内中断和外中断 <a class="header-anchor" href="#内中断和外中断" aria-label="Permalink to &quot;内中断和外中断&quot;">​</a></h3><p>内中断与外中断的核心区别在于触发源位置 —— 前者源于 CPU 内部逻辑，后者来自外部硬件设备，两者共同覆盖了系统运行中的各类事件处理需求。</p><p>内中断由 CPU 内部事件触发，源于程序执行中的异常情况或主动请求，属于 CPU 自身逻辑的一部分。其触发场景包括三类：故障类（除零错误、非法指令、内存访问越界等程序执行错误）、陷阱类（调试断点、syscall 系统调用等主动触发场景）、终止类（内存奇偶校验错误等严重故障，导致程序终止）。处理上具有响应速度快、无需外部信号等待的特点，通常涉及程序状态修复或系统级权限切换。</p><p>外中断由 CPU 外部硬件设备发起，通过中断请求线（IRQ）等硬件线路传递信号。触发场景包括外设交互（键盘按键、鼠标移动、硬盘读写完成）、时钟信号（系统定时器触发，支撑任务调度）、硬件故障（电源异常、风扇停转等传感器触发事件）。处理上依赖硬件电路与中断控制器（如 PIC/APIC），需考虑中断优先级与嵌套机制，确保关键设备（硬盘、网卡）优先响应。</p><h3 id="硬中断和软件中断" tabindex="-1">硬中断和软件中断 <a class="header-anchor" href="#硬中断和软件中断" aria-label="Permalink to &quot;硬中断和软件中断&quot;">​</a></h3><p>硬中断与软中断的划分依据是实现方式，前者依赖物理硬件电路，后者通过软件指令触发，适配不同的事件处理场景。</p><p>硬中断是外部硬件设备通过物理电路直接触发的中断，是传统中断形式，本质是硬件主动向 CPU 发起请求，无需软件干预，典型场景如键盘按键、硬盘 I/O 完成等，处理需依赖中断控制器识别中断源。</p><p>软中断是由软件指令主动触发的中断，无需外部硬件参与，本质是程序主动请求 CPU 执行特殊逻辑（如软件模拟中断），典型场景包括系统调用、调试断点等，核心作用是实现程序与系统内核的协作或特殊逻辑触发。</p><p>不同类型的中断各有其适配场景：内中断聚焦 CPU 内部逻辑与程序执行，外中断侧重外部硬件交互；硬中断依赖物理电路，软中断通过软件指令实现。这种分类体系让系统能根据不同事件的特性灵活调度处理资源，既保障了关键事件的优先级，又兼顾了处理效率与灵活性，是中断机制适配多元系统需求的核心设计。</p><h2 id="中断过程" tabindex="-1">中断过程 <a class="header-anchor" href="#中断过程" aria-label="Permalink to &quot;中断过程&quot;">​</a></h2><p>中断过程是中断机制的核心执行链路，从多个中断的优先级裁决，到 CPU 对中断请求的响应，每个环节都遵循严格的逻辑规则，确保中断处理有序、高效地完成，是连接中断请求与最终处理的关键桥梁。</p><h2 id="中断判优" tabindex="-1">中断判优 <a class="header-anchor" href="#中断判优" aria-label="Permalink to &quot;中断判优&quot;">​</a></h2><p>当多个中断源同时发起请求时，CPU 无法并行处理，中断判优作为核心调度环节，通过预设优先级规则与特定裁决方式，确定中断响应顺序，保障高紧急度事件优先处理，避免系统混乱。</p><p>中断优先级是判优的核心依据，即给不同中断源（如键盘、硬盘、定时器）划分 “紧急程度等级”：优先级高的中断不仅优先被响应，还能打断正在执行的低优先级中断处理（即中断嵌套）。多级中断的设计进一步拓展了系统处理紧急事件的能力，让关键任务始终获得资源倾斜。</p><p><img src="'+o+'" alt=""></p><p>如上图所示，中断判优主要通过两种方式实现：​</p><ul><li>**硬件判优：**依赖专用硬件电路（如中断控制器 APIC）自动完成裁决，无需 CPU 参与软件逻辑，核心优势是速度快、实时性强。其流程为：外部设备的中断请求先发送至中断控制器，控制器通过内部优先级比较电路（如优先级编码器）识别当前最高优先级中断，再直接向 CPU 发送该中断的响应信号，自动跳过低优先级请求。</li><li>**软件判优：**不依赖专用硬件，由 CPU 执行软件程序（如中断服务程序、操作系统内核逻辑），通过代码判断决定响应顺序，核心优势是灵活性高、可动态调整。其流程为：所有中断先触发 “公共中断入口”（如统一进入 irq_handler 函数），在入口中软件遍历中断源列表（如查询寄存器识别触发设备），再按预设优先级规则（如数组排序、配置文件设定）选择最高优先级中断进行处理（例如 A、B、C 三个中断按降序排列时，优先处理 A）。</li></ul><p>硬件判优保障了实时性需求，软件判优满足了灵活调整的场景，两种方式互补配合，让中断判优既能适配关键设备的快速响应需求，又能应对复杂系统的动态调度场景，为后续中断响应奠定有序基础。</p><h2 id="中断响应" tabindex="-1">中断响应 <a class="header-anchor" href="#中断响应" aria-label="Permalink to &quot;中断响应&quot;">​</a></h2><p><img src="'+p+'" alt=""></p><p>中断响应是 CPU 接收到中断请求后，从准备处理到启动处理的过渡环节，需满足特定条件、遵循固定时机与标准化方式，确保中断处理的准确性与安全性，是中断流程中连接请求与处理的关键步骤。</p><p>中断响应需同时满足四个核心条件：一是中断源发出有效请求，即硬件设备（如 I/O 接口）或软件（如异常指令）产生中断信号，并通过中断线传递给 CPU；二是 CPU 允许中断，即 CPU 内部的中断允许标志位（如 IF 标志）处于 “允许” 状态（IF=1），若被 CLI 等系统指令禁用，则无法响应外部中断；三是无更高优先级中断处理中，若 CPU 正处理高优先级中断或处于不可中断的临界区（如执行特权指令），会暂时忽略低优先级请求；四是指令执行阶段允许中断，部分长耗时指令（如乘法、除法）执行时，CPU 仅在特定阶段（如指令结束时）检查中断请求。</p><p>CPU 并非随时响应中断，而是在特定时机检测并处理请求，主要包括：当前指令执行完毕后（最常见时机，CPU 每条指令结束后会主动查询中断引脚）；异常事件发生时（如除零错误、地址越界，会立即终止当前指令并转入异常处理）；DMA 传输完成时（DMA 控制器完成数据传输后向 CPU 发中断，通知操作结束）；系统定时触发时（定时器如 PIT 按预设周期产生中断，用于任务调度、时钟更新等）。</p><p>中断响应的核心方式是 CPU 进入中断周期，一旦进入该周期，会由中断隐指令（硬件自动执行，无需软件干预）完成三项关键操作：关中断（避免后续中断干扰当前响应流程）、保护程序断点（保存当前 PC 指针、寄存器状态等，为后续返回做准备）、寻找中断服务程序（ISR）入口地址（确定中断处理的具体程序位置）。</p><p>中断响应的条件、时机与方式共同构成了严格的执行规范：条件确保中断请求合法有效，时机保障 CPU 当前操作不受干扰，方式则为中断处理做好前期准备，三者缺一不可，为后续中断处理的顺利开展提供了坚实保障。</p><h2 id="中断处理" tabindex="-1">中断处理 <a class="header-anchor" href="#中断处理" aria-label="Permalink to &quot;中断处理&quot;">​</a></h2><p>中断处理是中断周期的核心执行环节，衔接中断响应与原程序恢复，通过标准化的步骤完成中断事件处理、现场保护与状态还原，既要确保中断处理逻辑的有效执行，也要保障原程序能在中断结束后准确续行，是中断机制落地的关键流程。</p><p><img src="'+h+'" alt=""></p><p>正常情况下，CPU 循环执行 “取指令→执行指令” 的基本流程：取指令阶段从内存读取待执行指令存入指令寄存器（IR），执行指令阶段由运算器与控制器配合完成指令功能（如运算、数据传输）；每执行完一条指令，CPU 会自动检查是否存在有效中断请求，若检测到（如外设信号、软件异常等），则进入中断周期，按以下核心步骤完成处理：​</p><ol><li>响应中断并关中断：CPU 确认中断请求后正式启动处理流程，通过硬件或软件指令（如 CLI）关闭中断允许标志（中断屏蔽置位），禁止新的中断嵌套，避免当前处理过程被干扰（后续可按需重新开中断）；</li><li>保存现场关键信息：为确保中断结束后能正确返回原程序，需先保存程序计数器（PC）的值（记录原程序中断位置），再将通用寄存器、状态寄存器（如标志位）等核心数据存入栈或内存，形成完整 “现场”，防止中断处理修改这些值影响原程序执行；</li><li>转移至中断服务子程序：CPU 通过中断源的 “中断向量” 或查询中断表，快速定位并跳转到对应的中断服务子程序（ISR）入口地址，开启具体中断处理；</li><li>开中断：通过指令（如 STI）重新允许中断，使 CPU 能响应新的高优先级中断请求（若需支持中断嵌套，也可在 “设备服务” 阶段提前开中断）；</li><li>执行中断服务程序：作为中断处理的核心，该程序需完成具体业务逻辑，如外设数据读取、异常修复、故障记录等核心功能；</li><li>关中断：为避免恢复现场过程被新中断干扰，需再次关闭中断，保障现场还原与屏蔽字设置的稳定性；</li><li>恢复 CPU 现场：将之前保存的通用寄存器、状态寄存器等数据恢复原值，让 CPU 回到中断前的运行状态；</li><li>返回原程序：从栈中取出保存的 PC 值，跳转回原程序被中断的位置，恢复 “取指令→执行指令” 的正常循环。</li></ol><p>中断处理的核心价值在于 “有序处理” 与 “无损还原”：通过关中断、保存现场等步骤保障中断处理的独立性，通过精准的现场恢复与程序跳转确保原程序不受影响，既高效完成了中断事件的响应，又维持了系统运行的连续性与稳定性。</p><h2 id="中断向量" tabindex="-1">中断向量 <a class="header-anchor" href="#中断向量" aria-label="Permalink to &quot;中断向量&quot;">​</a></h2><p>中断向量是连接中断源与中断服务程序（ISR）的关键 “索引机制”，核心作用是建立 “中断源→ISR 入口地址” 的映射关系，帮助 CPU 快速定位中断处理代码，避免低效的轮询查找，是提升中断响应效率的核心设计。</p><h3 id="什么是中断向量" tabindex="-1">什么是中断向量？ <a class="header-anchor" href="#什么是中断向量" aria-label="Permalink to &quot;什么是中断向量？&quot;">​</a></h3><p>明确中断向量相关术语的定义与关联，是理解后续定位方法的基础，其核心逻辑围绕 “快速索引” 展开，为中断处理的高效跳转提供支撑。</p><p>向量中断是一种高效的中断响应机制，核心特点是通过硬件自动传递 “中断向量（类型号）”，让 CPU 无需软件轮询即可直接定位 ISR 入口；中断向量本质是包含 “中断源与 ISR 入口地址映射关系” 的数据结构，核心作用是为 CPU 提供快速索引 —— 当中断发生时，CPU 获取中断类型号后，可通过查询中断向量表直接找到 ISR 地址，无需手动遍历；中断向量地址则是存储该映射关系的内存单元地址，是 CPU 访问中断向量的物理入口。</p><p>这三个概念层层递进：向量中断是响应模式，中断向量是映射核心，中断向量地址是物理载体，三者共同构成了 “快速定位 ISR” 的基础逻辑，为后续硬件与软件两种定位方法提供了理论支撑。</p><h3 id="硬件向量法" tabindex="-1">硬件向量法 <a class="header-anchor" href="#硬件向量法" aria-label="Permalink to &quot;硬件向量法&quot;">​</a></h3><p><img src="'+s+'" alt=""></p><p>硬件向量法是依托硬件电路实现中断源与 ISR 快速关联的定位方式，核心优势是速度快、无需软件轮询，适配对实时性要求较高的场景，是主流的中断定位方案之一。</p><p>其实现流程遵循标准化逻辑：​</p><ol><li>中断触发：外设（如键盘、硬盘）或内部异常通过硬件引脚向 CPU 发送中断请求信号；</li><li>向量地址生成：由中断向量地址形成部件（本质是硬件编码器，可集成在 CPU 或接口电路中），根据中断源的优先级、身份等信息生成唯一向量地址（如 0x0B）；</li><li>定位服务程序：主要有两种方式 —— 一是向量地址中存储无条件转移指令（如 JMP ISR 入口），CPU 执行指令直接跳转；二是通过中断向量表定位，向量地址作为表的索引，对应存储单元记录 ISR 入口地址，CPU 访问该地址即可获取；</li><li>执行服务程序：完成现场保护、设备服务（如数据读取、错误处理）、现场恢复等操作后，返回原程序。</li></ol><p>硬件向量法通过硬件电路简化了定位流程，规避了软件查询的耗时问题，能快速响应关键设备的中断请求，是工业控制、实时系统等场景的核心选择，其高效性与稳定性直接提升了系统的中断处理能力。</p><h3 id="软件查询法" tabindex="-1">软件查询法 <a class="header-anchor" href="#软件查询法" aria-label="Permalink to &quot;软件查询法&quot;">​</a></h3><p>软件查询法是不依赖硬件电路，完全通过软件逻辑实现 ISR 定位的方式，核心优势是灵活便捷、无需专用硬件支持，适配简单系统或对实时性要求不高的场景。</p><p>其核心逻辑为：当中断发生后，CPU 执行查询程序遍历所有中断源，若检测到某一中断源有有效请求，便通过预设的转移指令直接跳转到该中断源对应的 ISR 入口地址，进而启动中断处理；ISR 的入口地址由程序员提前定义，可根据系统需求灵活调整。这种方式无需硬件编码器、中断向量表等专用组件，适配各类简单系统，但由于需要遍历中断源，查询时间较长，实时性相对较差（例如 8 个按优先级降序排列的中断源，最坏情况下需遍历全部 8 个才能定位）。</p><p>软件查询法以灵活性弥补了实时性的不足，无需额外硬件成本，适合资源有限的简单嵌入式系统或中断源数量较少的场景，与硬件向量法形成互补，覆盖了不同系统的中断定位需求。</p><p>中断向量的核心价值在于建立 “中断源→ISR” 的快速映射，而硬件向量法与软件查询法分别从 “高效” 与 “灵活” 两个维度适配不同场景：硬件法保障实时性，软件法降低部署成本，两者共同构成了中断定位的完整解决方案，为中断处理的高效执行提供了关键支撑。</p><h2 id="多重中断" tabindex="-1">多重中断 <a class="header-anchor" href="#多重中断" aria-label="Permalink to &quot;多重中断&quot;">​</a></h2><p>多重中断（又称中断嵌套）是中断机制的进阶设计，核心是允许高优先级中断打断低优先级中断的处理流程，其本质是通过优先级仲裁与断点保护，实现 “紧急事件优先响应”，大幅提升系统对关键任务的实时处理能力，是复杂系统中断管理的核心功能之一。</p><h3 id="多重中断概念" tabindex="-1">多重中断概念 <a class="header-anchor" href="#多重中断概念" aria-label="Permalink to &quot;多重中断概念&quot;">​</a></h3><p>多重中断指 CPU 在处理某一中断时，若收到更高优先级的中断请求，会暂停当前中断服务程序，转而处理高优先级中断，完成后再返回继续执行原中断程序（如键盘中断处理中响应硬盘故障中断）；与之相对，单重中断在处理过程中不允许任何新中断打断现行服务程序。实现多重中断的核心方法是：在中断服务程序起始部分完成现场保存后，发送新屏蔽字（屏蔽同级别及低优先级中断），再执行开中断指令，为高优先级中断嵌套放行。例如：CPU 正在处理键盘中断时，突然收到硬盘故障的紧急中断（优先级更高），会暂停键盘处理，转而处理硬盘中断，完成后再返回继续处理键盘中断。</p><p><img src="'+n+'" alt=""></p><ol><li>单重中断：CPU在响应处理中断过程中，不允许中断现行的中断服务程序</li><li>多重中断：CPU在响应处理中断过程中，允许更高级别的中断源出现，中断现行的中断服务程序。</li><li>实现多重中断的方法是在中断服务程序的起始部分保存现场、送新屏蔽字以屏蔽同级别和低级别的中断请求、然后开中断，这样 CPU 就可响应更高级别的中断请求，实现多重中断。</li></ol><h3 id="实现多重中断的条件" tabindex="-1">实现多重中断的条件 <a class="header-anchor" href="#实现多重中断的条件" aria-label="Permalink to &quot;实现多重中断的条件&quot;">​</a></h3><p>多重中断的有序执行需满足三大核心条件，这些条件相互配合，既确保高优先级中断能正常嵌套，又避免系统陷入混乱，是实现中断嵌套的关键保障。</p><ol><li>开中断指令控制：CPU 响应中断后默认关中断，需在中断服务程序完成关键现场保护后，主动执行开中断指令（如 STI），为高优先级中断请求提供响应通道。</li><li>优先级仲裁规则：为所有中断源划分明确优先级，遵循 “高优先级可打断低优先级，同级别、低优先级需排队等待” 的规则，由硬件或 CPU 逻辑自动识别优先级，保障处理顺序有序。</li><li>屏蔽技术辅助：通过中断控制器的屏蔽寄存器（如 IMR）或软件逻辑，在处理高优先级中断时屏蔽低优先级请求，待高优先级中断完成后再解除屏蔽，避免低优先级中断干扰关键流程。</li></ol><p>这三个条件层层递进：开中断指令是嵌套的 “开关”，优先级规则是嵌套的 “秩序”，屏蔽技术是嵌套的 “防护”，三者共同确保多重中断既能灵活嵌套，又能维持系统稳定。</p><h3 id="多重中断的断点保护" tabindex="-1">多重中断的断点保护 <a class="header-anchor" href="#多重中断的断点保护" aria-label="Permalink to &quot;多重中断的断点保护&quot;">​</a></h3><p><img src="'+d+'" alt=""></p><p>断点保护是多重中断的核心支撑，其目标是保存每一层被打断程序的执行位置，确保所有嵌套中断处理完成后，能逐层返回原程序继续执行，核心依赖 “后进先出” 的存储逻辑。</p><ol><li>**断点进栈（主流方式，流程图体现）：**利用栈 “后进先出” 的特性，每次中断时，自动把当前 PC（程序下一条地址）压入栈（流程图里的 “程序断点进栈” ）。内层中断的断点存在栈顶，外层在栈底；返回时按 “后进先出” 弹出，先恢复内层，再恢复外层。</li><li>**断点存入 “0 地址”（早期简单方式）：**把断点（PC 值）直接写入内存地址0，由 “中断隐指令” 执行 4 步：0→MAR→写命令→PC→MDR→存入地址0 。只能存 1 个断点，多重中断会覆盖旧断点，导致外层中断无法恢复，现已淘汰。</li></ol><p>断点保护的核心价值是 “无损还原”，通过合理的存储方式记录每层中断的执行位置，解决了多重中断中 “嵌套后如何逐层返回” 的关键问题，是多重中断能稳定运行的基础。</p><h2 id="中断屏蔽" tabindex="-1">中断屏蔽 <a class="header-anchor" href="#中断屏蔽" aria-label="Permalink to &quot;中断屏蔽&quot;">​</a></h2><p>中断屏蔽是通过软件配置控制中断响应的核心机制，借助屏蔽字（Mask）与相关寄存器，实现对不同中断源的 “允许 / 禁止” 精准管控，既能屏蔽无关中断避免干扰，又能动态调整中断处理优先级，是中断系统灵活性与稳定性的重要保障。</p><h3 id="什么是屏蔽字" tabindex="-1">什么是屏蔽字? <a class="header-anchor" href="#什么是屏蔽字" aria-label="Permalink to &quot;什么是屏蔽字?&quot;">​</a></h3><p><img src="'+C+'" alt=""></p><p>屏蔽字（Mask） 是用于控制中断系统行为的重要机制，主要作用是决定哪些中断请求可以被响应，哪些会被暂时屏蔽（忽略）。一般而言屏蔽字是一组二进制数（或二进制位集合），通常存储在中断屏蔽寄存器（Interrupt Mask Register, IMR）中。每个二进制位与一个中断源一一对应，通过位值控制响应：</p><ul><li>屏蔽位 = “1”：屏蔽对应中断源请求，CPU 暂时不响应；</li><li>屏蔽位 = “0”：允许对应中断源请求，CPU 可正常响应。</li></ul><p>通过软件配置动态调整硬件中断处理逻辑，无需修改硬件电路即可灵活调整中断响应策略，是中断管理的关键环节。屏蔽字的设计实现了 “软件管控硬件中断” 的核心目标，通过简单的二进制位配置，即可精准控制每个中断源的响应状态，为后续动态调整优先级、避免中断干扰提供了核心工具。</p><h3 id="屏蔽字的设置方法" tabindex="-1">屏蔽字的设置方法 <a class="header-anchor" href="#屏蔽字的设置方法" aria-label="Permalink to &quot;屏蔽字的设置方法&quot;">​</a></h3><p>屏蔽字的设置需遵循特定时机与规则，确保中断嵌套有序且不发生冲突，其设置逻辑与中断服务程序的执行流程紧密相关。</p><ul><li>设置时机：必须安排在中断服务程序的开中断指令之前，避免新中断在屏蔽字配置完成前触发，导致管控失效。</li><li>配置规则：按中断优先级需求设置对应位值，例如：</li><li>系统有 16 个中断源，优先级按 1~16 降序排列；</li><li>需屏蔽 5~16 级中断时，将对应二进制位设为 “1”，1~4 级设为 “0”。</li></ul><p>这一设置规则的核心是 “先管控后开放”，确保屏蔽字在中断嵌套允许前生效，避免因配置时机不当导致的中断混乱，为后续调整处理优先级奠定基础。</p><h3 id="屏蔽技术可以改变处理优先等级" tabindex="-1">屏蔽技术可以改变处理优先等级 <a class="header-anchor" href="#屏蔽技术可以改变处理优先等级" aria-label="Permalink to &quot;屏蔽技术可以改变处理优先等级&quot;">​</a></h3><p>中断的响应优先级由硬件预设后不可改变，但通过重新设置屏蔽字，可动态调整中断的处理优先级，实现 “响应优先级与处理优先级分离”，大幅提升中断管理的灵活性。不改变硬件预设的响应优先级，仅通过软件配置屏蔽字，屏蔽低优先级或非关键中断，让目标中断（如示例中的 D）提前执行。</p><p>示例:下图响应优先级按 A→&gt;B→C→&gt;D 降序排列,处理优先级按 A→D→C→&gt;B 降序排列。</p><p><img src="'+P+'" alt=""></p><ol><li>程序执行过程中，若 A、8、C、D 四个中断源同时提出请求，按照中断级别的高低，CPU 首先响应并处理 A中断源的请求,由于A的屏蔽字是 1111,屏蔽了所有的中断源.故 A程序可以全部执行完，然后回到主程序。</li><li>由于 B、C、D 的中断请求还未响应，而B的响应优先级高于其他，所以 CPU 响应B 的请求，进入B的中断服务程序。</li><li>在B的服务程序中，由于设置了新的屏蔽字 0100，即 A、C、D 可打断 B，而A程序已经执行完，C的响应优先级又高于 D，于是 CPU 响应C，进入c的服务程序。</li><li>在C的服务程序中，由于设置了新的屏蔽字 0110，即 A、D 可打断 c，由于 A程序已经执行完，于是 CPU 响应 D，执行D的服务程序。</li><li>在D的服务程序中，屏蔽字变成 0111，即只有A可打断 D，但A已经处理结束所以D可以一直做完，然后回到C程序，C程序执行完，回到B程序，B程序做完，后回到主程序，至此，A、B、C、D 均处理完毕。</li></ol><h3 id="新屏蔽字的设置流程" tabindex="-1">新屏蔽字的设置流程 <a class="header-anchor" href="#新屏蔽字的设置流程" aria-label="Permalink to &quot;新屏蔽字的设置流程&quot;">​</a></h3><p>新屏蔽字的设置需遵循标准化流程，确保屏蔽配置的准确性与连贯性，避免因流程缺失导致的中断管控失效。</p><ol><li>保存旧屏蔽字：在中断服务程序中保存当前屏蔽字，以便后续恢复系统原有响应策略；</li><li>设置新屏蔽字：根据当前中断优先级需求，计算并配置新屏蔽字（明确屏蔽同级别 / 低优先级，允许高优先级）；</li><li>开中断生效：执行开中断指令（如 STI），使新屏蔽字生效，允许高优先级中断嵌套；</li><li>恢复旧屏蔽字：当前中断处理完成后，恢复之前保存的旧屏蔽字，还原系统原始中断响应策略；</li></ol><p>这一标准化流程既保障了新屏蔽字能精准管控当前中断的嵌套逻辑，又通过旧屏蔽字的恢复确保系统整体中断策略不受影响，实现了 “局部调整不干扰全局” 的目标，是屏蔽技术稳定应用的关键。</p><h2 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【国家电网2016】用户程序发出磁盘 I/O 请求后，系统的处理流程是：用户程序→系统调用处理程序→设备驱动程序→中断处理程序。其中，计算数据所在磁盘的柱面号、磁头号、扇区号的程序是（）。A.用户程序B.系统调用处理程序C.设备驱动程序D.中断处理程序答案 ：C解析 ：设备驱动程序负责与硬件设备交互，计算磁盘物理地址（柱面号、磁头号、扇区号）等底层操作</th></tr></thead></table><table tabindex="0"><thead><tr><th>【工商银行2022】中断是指 CPU 对 I/O 设备发来的中断信号的一种响应，在接收到中断信号后，CPU 暂停正在执行的程序，保留 CPU 环境后，自动执行该 I/O 设备的中断处理程序。请问保留 CPU 环境的操作是什么？A.寄存器中的所有数据存入硬盘；B.阻塞正在执行的程序进程；C.把正运行程序所占用的内存对换到磁盘的对换区中；D.寄存器中的所有数据存入内存答案 ：D解析 ：中断处理的核心是 保存现场（保留 CPU 环境） 与 恢复现场 。保留 CPU 环境需将 CPU 当前寄存器（如程序计数器、状态寄存器等核心运行数据）的内容临时存入内存，确保中断处理完成后能准确恢复原程序的执行状态。A 选项“存入硬盘”速度过慢，不符合中断处理的实时性要求；B 选项“阻塞进程”是进程管理的操作，与“保留 CPU 环境”无关；C 选项“内存对换”是虚拟内存机制，用于解决内存不足问题，并非中断处理的步骤</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网2016】下列中断类型中，属于强迫性中断的是（）A. 主存校验错（硬件故障中断）；B. 程序性中断；C. 外部中断；D. I/O 中断答案 ：ABCD解析 ：主存校验错属于硬件故障中断，与程序性、外部、I/O 中断均为强迫性中断，故全选</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网2021】中断响应是解决中断的发现和接收问题的，是由中断装置完成的。中断响应是硬件对中断请求作出响应的过程，包括（）。A. 识别中断源；B. 保留现场；C. 引出中断处理程序；D. 处理中断事件。答案：ABC解析：中断响应是硬件对中断请求的响应过程，核心步骤包括识别中断源、保存当前程序现场、跳转至中断处理程序，不涉及“处理中断事件”（属于中断处理阶段）</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网2016】下列关于中断 I/O 方式和 DMA 方式比较的叙述中，错误的是（）。A. 中断 I/O 方式请求的是 CPU 处理时间，DMA 方式请求的是总线使用权；B. 中断响应发生在一条指令执行结束后，DMA 响应发生在一个总线事务完成后；C. 中断 I/O 方式下数据传送通过软件完成，DMA 方式下数据传送由硬件完成；D. 中断 I/O 方式适用于所有外部设备，DMA 方式仅适用于快速外部设备。答案：D解析：中断 I/O 方式并非适用于所有外部设备，如高速设备（如硬盘）更适合 DMA 方式，故 D 错误</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网2018】在关中断状态，不可响应的中断是（）。A. 可屏蔽中断；B. 不可屏蔽中断；C. 软件中断；D. 硬件中断。答案：A解析：关中断状态下，CPU 会屏蔽“可屏蔽中断”（如外设请求），但仍会响应“不可屏蔽中断”（如硬件故障</th></tr></thead></table><table tabindex="0"><thead><tr><th>【南方电网2020】发生中断请求的不可能条件是（ ）。A. 一条指令执行结束；B. 一次 I/O 操作开始；C. 机器内部发生故障；D. 一次 DMA 操作开始。答案：A解析：“一条指令执行结束”是 CPU 响应中断的时机（确保当前指令完整执行），而非“中断请求”的触发条件；I/O 开始、硬件故障、DMA 开始均可能触发中断请求</th></tr></thead></table><table tabindex="0"><thead><tr><th>【中国铁塔2016】中断向量地址是（ ）。A. 子程序入口地址；B. 中断服务例行程序入口地址；C. 中断返回地址；D. 中断服务例行程序入口地址的指示器。答案：D解析：中断向量地址指向“中断向量表”中的条目，该条目存储中断服务程序的入口地址，因此是“入口地址的指示器”</th></tr></thead></table>',108)])])}const g=e(c,[["render",b]]);export{f as __pageData,g as default};
